CREATE INDEX IF NOT EXISTS bookstore_supplier_import_jobs_created_idx ON bookstore_supplier_import_jobs (created_at DESC);
CREATE TABLE IF NOT EXISTS equipment_categories ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, parent_id TEXT REFERENCES equipment_categories(id) ON DELETE SET NULL, sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
