CREATE TABLE IF NOT EXISTS equipment_products ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', brand TEXT, sku TEXT, category_id TEXT NOT NULL REFERENCES equipment_categories(id) ON DELETE RESTRICT, phase_tags TEXT NOT NULL DEFAULT '[]', grade_min INTEGER NOT NULL DEFAULT 0, grade_max INTEGER NOT NULL DEFAULT 12, subject_tags TEXT NOT NULL DEFAULT '[]', tags TEXT NOT NULL DEFAULT '[]', price_cents INTEGER NOT NULL DEFAULT 0, currency TEXT NOT NULL DEFAULT 'ZAR', images TEXT NOT NULL DEFAULT '[]', fulfillment_type TEXT NOT NULL, stock_qty INTEGER, lead_time_days INTEGER, attributes_json TEXT NOT NULL DEFAULT '{}', is_bundle INTEGER NOT NULL DEFAULT 0, bundle_items_json TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX IF NOT EXISTS equipment_products_category_idx ON equipment_products(category_id);
CREATE INDEX IF NOT EXISTS equipment_products_grade_idx ON equipment_products(grade_min, grade_max);
CREATE INDEX IF NOT EXISTS equipment_products_fulfillment_idx ON equipment_products(fulfillment_type);
CREATE TABLE IF NOT EXISTS wallet_accounts ( user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, balance_credits BIGINT NOT NULL DEFAULT 0, currency TEXT NOT NULL DEFAULT 'ZAR', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), CHECK (balance_credits >= 0) );
CREATE INDEX IF NOT EXISTS wallet_accounts_created_idx ON wallet_accounts (created_at DESC);
CREATE TABLE IF NOT EXISTS wallet_ledger_entries ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, type TEXT NOT NULL, amount_credits BIGINT NOT NULL, reason TEXT NOT NULL, ref_type TEXT, ref_id TEXT, idempotency_key TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), CHECK (type IN ('CREDIT', 'DEBIT')), CHECK (amount_credits > 0) );
CREATE INDEX IF NOT EXISTS wallet_ledger_user_created_idx ON wallet_ledger_entries (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS wallet_ledger_ref_idx ON wallet_ledger_entries (ref_type, ref_id);
CREATE TABLE IF NOT EXISTS wallet_topups ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, provider TEXT NOT NULL, provider_ref TEXT UNIQUE, amount_zar NUMERIC(12, 2) NOT NULL, credits_granted BIGINT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), CHECK (amount_zar > 0), CHECK (credits_granted > 0), CHECK (status IN ('pending', 'succeeded', 'failed', 'canceled')) );
CREATE INDEX IF NOT EXISTS wallet_topups_user_created_idx ON wallet_topups (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS wallet_topups_status_created_idx ON wallet_topups (status, created_at DESC);
CREATE TABLE IF NOT EXISTS processed_webhook_events ( provider TEXT NOT NULL, event_id TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY (provider, event_id) );
CREATE TABLE IF NOT EXISTS wallet_free_unlock_usage ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, feature_key TEXT NOT NULL, week_start DATE NOT NULL, attempt_ref_id TEXT, idempotency_key TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), CHECK (feature_key <> '') );
CREATE UNIQUE INDEX IF NOT EXISTS wallet_free_unlock_usage_weekly_idx ON wallet_free_unlock_usage (user_id, feature_key, week_start);
CREATE INDEX IF NOT EXISTS wallet_free_unlock_usage_feature_week_idx ON wallet_free_unlock_usage (feature_key, week_start DESC);
CREATE INDEX IF NOT EXISTS wallet_free_unlock_usage_user_created_idx ON wallet_free_unlock_usage (user_id, created_at DESC);
CREATE TABLE IF NOT EXISTS pricing_experiments ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), start_date TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), end_date TEXT, detailed_report_price_credits INTEGER NOT NULL CHECK (detailed_report_price_credits > 0), weekly_free_unlocks INTEGER NOT NULL CHECK (weekly_free_unlocks >= 0), bundle_structure_json TEXT NOT NULL DEFAULT '[]', created_by_admin TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), CHECK (end_date IS NULL OR end_date >= start_date) );
CREATE INDEX IF NOT EXISTS pricing_experiments_start_idx ON pricing_experiments (start_date DESC);
CREATE INDEX IF NOT EXISTS pricing_experiments_created_by_idx ON pricing_experiments (created_by_admin, created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS pricing_experiments_single_active_idx ON pricing_experiments ((1)) WHERE end_date IS NULL;
CREATE TABLE brand_signals ( id INTEGER PRIMARY KEY, source TEXT NOT NULL CHECK (source IN ('github','trading','ideas','price','manual','telegram')), raw_content TEXT NOT NULL, pillar TEXT NOT NULL CHECK (pillar IN ('trading','school','aura','builder')), processed INTEGER DEFAULT 0, created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE TABLE brand_drafts ( id INTEGER PRIMARY KEY, signal_id INT REFERENCES brand_signals(id) ON DELETE CASCADE, platform TEXT NOT NULL CHECK (platform IN ('x','linkedin','instagram','youtube')), content TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','scheduled','published','failed','skipped')), scheduled_at TEXT, published_at TEXT, external_id TEXT, error_msg TEXT, retry_count INT DEFAULT 0, created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE TABLE brand_analytics ( id INTEGER PRIMARY KEY, draft_id INT REFERENCES brand_drafts(id) ON DELETE CASCADE, platform TEXT NOT NULL, impressions INT DEFAULT 0, engagements INT DEFAULT 0, likes INT DEFAULT 0, reposts INT DEFAULT 0, comments INT DEFAULT 0, follows_gained INT DEFAULT 0, fetched_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE TABLE brand_voice_model ( id INTEGER PRIMARY KEY, version INT NOT NULL UNIQUE, system_prompt TEXT NOT NULL, examples TEXT NOT NULL DEFAULT '[]', active INTEGER DEFAULT 0, created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE UNIQUE INDEX brand_voice_model_active_idx ON brand_voice_model(active) WHERE active = 1;
CREATE TABLE brand_content_fingerprints ( id INTEGER PRIMARY KEY, fingerprint TEXT NOT NULL UNIQUE, draft_id INT REFERENCES brand_drafts(id), expires_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now','+7 day')) );
CREATE INDEX brand_signals_processed_idx ON brand_signals(processed, created_at DESC);
CREATE INDEX brand_drafts_status_idx ON brand_drafts(status, scheduled_at);
CREATE INDEX brand_drafts_platform_idx ON brand_drafts(platform, status);
CREATE INDEX brand_analytics_draft_idx ON brand_analytics(draft_id, fetched_at DESC);
CREATE TABLE IF NOT EXISTS university_plans ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), user_id TEXT REFERENCES users(id) ON DELETE CASCADE, file_name TEXT, file_key TEXT, extracted_text TEXT, uploaded_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX IF NOT EXISTS university_plans_user_uploaded_idx ON university_plans (user_id, uploaded_at DESC);
CREATE TABLE IF NOT EXISTS institutions ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), name TEXT NOT NULL, short_name TEXT, domain TEXT UNIQUE, type TEXT CHECK (type IN ('school','university')), province TEXT, country TEXT DEFAULT 'ZA', is_active INTEGER DEFAULT 1, created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
