CREATE TABLE IF NOT EXISTS topics ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), subject TEXT NOT NULL, name TEXT NOT NULL, grade INTEGER, phase TEXT, term INTEGER, week INTEGER, bloom_level TEXT CHECK (bloom_level IN ( 'remember','understand','apply', 'analyse','evaluate','create' )), caps_aligned INTEGER DEFAULT 1, created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE TABLE IF NOT EXISTS weakness_signals ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, topic_id TEXT REFERENCES topics(id), subject TEXT NOT NULL, topic_text TEXT NOT NULL, signal_type TEXT NOT NULL CHECK (signal_type IN ( 'wrong_answer', 'repeated_question', 'low_quiz_score', 'explicit_struggle', 'time_spent_high' )), score FLOAT CHECK (score >= 0 AND score <= 1), session_id TEXT, recorded_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE TABLE IF NOT EXISTS ai_session_topics ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), session_id TEXT NOT NULL, topic_text TEXT NOT NULL, subject_inferred TEXT, grade_inferred INTEGER, weakness_detected INTEGER DEFAULT 0, difficulty_level INTEGER CHECK ( difficulty_level BETWEEN 1 AND 5 ), created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE TABLE IF NOT EXISTS questions ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), topic_id TEXT REFERENCES topics(id), subject TEXT NOT NULL, grade INTEGER, question_text TEXT NOT NULL, answer TEXT NOT NULL, difficulty INTEGER DEFAULT 3 CHECK ( difficulty BETWEEN 1 AND 5 ), bloom_level TEXT CHECK (bloom_level IN ( 'remember','understand','apply', 'analyse','evaluate','create' )), source TEXT DEFAULT 'ai_generated', is_active INTEGER DEFAULT 1, created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE TABLE IF NOT EXISTS quiz_sessions ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, quiz_date DATE NOT NULL DEFAULT CURRENT_DATE, questions_total INTEGER DEFAULT 5, questions_correct INTEGER DEFAULT 0, score_percent FLOAT, completed INTEGER DEFAULT 0, completed_at TEXT, created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(user_id, quiz_date) );
CREATE TABLE IF NOT EXISTS quiz_answers ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), quiz_session_id TEXT NOT NULL REFERENCES quiz_sessions(id) ON DELETE CASCADE, question_id TEXT REFERENCES questions(id), question_text TEXT NOT NULL, correct_answer TEXT NOT NULL, student_answer TEXT, is_correct INTEGER, answered_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
