CREATE TABLE IF NOT EXISTS concept_dictionary ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), institution_id TEXT REFERENCES institutions(id) ON DELETE SET NULL, module_code TEXT NOT NULL DEFAULT '__institution__', concept_key TEXT NOT NULL, concept_label TEXT NOT NULL, aliases TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE (module_code, concept_key) );
CREATE INDEX IF NOT EXISTS idx_concept_dictionary_institution ON concept_dictionary (institution_id);
