CREATE INDEX IF NOT EXISTS idx_learning_events_user_concept_created ON learning_events (user_id, concept_key, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_learning_events_user_module_created ON learning_events (user_id, module_code, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_learning_events_user_personalization ON learning_events (user_id, excluded_from_personalization);
CREATE TABLE IF NOT EXISTS student_concept_state ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, module_code TEXT NOT NULL DEFAULT '__general__', concept_key TEXT NOT NULL, concept_label TEXT NOT NULL, mastery_score NUMERIC(4,3) NOT NULL DEFAULT 0.0 CHECK (mastery_score BETWEEN 0 AND 1), exposure_count INTEGER NOT NULL DEFAULT 0, struggle_count INTEGER NOT NULL DEFAULT 0, resource_open_count INTEGER NOT NULL DEFAULT 0, quiz_correct_count INTEGER NOT NULL DEFAULT 0, quiz_incorrect_count INTEGER NOT NULL DEFAULT 0, is_new_concept INTEGER NOT NULL DEFAULT 1, is_struggling INTEGER GENERATED ALWAYS AS (struggle_count > 2) STORED, last_seen_at TEXT, last_practiced_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE (user_id, module_code, concept_key) );
CREATE INDEX IF NOT EXISTS idx_student_concept_state_user_module ON student_concept_state (user_id, module_code);
CREATE INDEX IF NOT EXISTS idx_student_concept_state_user_score ON student_concept_state (user_id, mastery_score ASC, updated_at DESC);
ALTER TABLE bookstore_products ADD COLUMN concepts TEXT NOT NULL DEFAULT '[]';
CREATE TABLE IF NOT EXISTS posts ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, institution_id TEXT REFERENCES institutions(id) ON DELETE SET NULL, module_code TEXT, content TEXT NOT NULL, post_type TEXT NOT NULL DEFAULT 'general', audience TEXT NOT NULL DEFAULT 'campus', image_urls TEXT NOT NULL DEFAULT '{}', attachment_url TEXT, accepted_answer_id TEXT, is_hidden INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), CHECK (post_type IN ('general', 'question', 'resource', 'announcement')), CHECK (audience IN ('campus', 'faculty', 'module', 'public')) );
CREATE INDEX IF NOT EXISTS posts_institution_created_idx ON posts (institution_id, created_at DESC);
CREATE INDEX IF NOT EXISTS posts_module_created_idx ON posts (module_code, created_at DESC);
CREATE TABLE IF NOT EXISTS post_reactions ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, reaction_type TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE (post_id, user_id, reaction_type), CHECK ( reaction_type IN ( 'got_it', 'same_question', 'great_explanation', 'saving_this', 'exam_relevant' ) ) );
CREATE INDEX IF NOT EXISTS post_reactions_post_idx ON post_reactions (post_id, created_at DESC);
CREATE TABLE IF NOT EXISTS comments ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, content TEXT NOT NULL, parent_comment_id TEXT REFERENCES comments(id) ON DELETE CASCADE, is_hidden INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX IF NOT EXISTS comments_post_created_idx ON comments (post_id, created_at ASC);
CREATE TABLE IF NOT EXISTS module_rooms ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), institution_id TEXT REFERENCES institutions(id) ON DELETE CASCADE, module_code TEXT NOT NULL, module_name TEXT NOT NULL, pinned_post_id TEXT REFERENCES posts(id) ON DELETE SET NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE (institution_id, module_code) );
CREATE INDEX IF NOT EXISTS module_rooms_code_idx ON module_rooms (module_code);
CREATE TABLE IF NOT EXISTS follows ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), follower_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, following_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE (follower_id, following_id), CHECK (follower_id <> following_id) );
CREATE TABLE IF NOT EXISTS community_reports ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), reporter_id TEXT REFERENCES users(id) ON DELETE SET NULL, content_type TEXT NOT NULL, content_id TEXT NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), CHECK (content_type IN ('post', 'comment', 'profile')), CHECK (reason IN ('spam', 'inappropriate', 'misinformation', 'harassment', 'off_topic')), CHECK (status IN ('pending', 'reviewed', 'actioned')) );
CREATE INDEX IF NOT EXISTS community_reports_status_idx ON community_reports (status, created_at DESC);
CREATE TABLE IF NOT EXISTS universities ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), name TEXT NOT NULL, short_code TEXT NOT NULL UNIQUE, country TEXT NOT NULL DEFAULT 'ZA', student_system TEXT NOT NULL CHECK (student_system IN ('campusnexus', 'peoplesoft', 'moodle', 'its', 'other')), calendar_url TEXT, exam_timetable_url TEXT, class_timetable_url TEXT, yearbook_url TEXT, portal_url TEXT, is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE TABLE IF NOT EXISTS university_campuses ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), university_id TEXT NOT NULL REFERENCES universities(id) ON DELETE CASCADE, campus_name TEXT NOT NULL, campus_code TEXT NOT NULL, city TEXT, province TEXT, is_primary INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE (university_id, campus_code) );
CREATE TABLE IF NOT EXISTS academic_calendars ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), university_id TEXT REFERENCES universities(id) ON DELETE CASCADE, campus_id TEXT REFERENCES university_campuses(id) ON DELETE SET NULL, year INTEGER NOT NULL, label TEXT NOT NULL, event_type TEXT NOT NULL CHECK (event_type IN ( 'semester_start', 'semester_end', 'exam_opp1_start', 'exam_opp1_end', 'exam_opp2_start', 'exam_opp2_end', 'exam_opp3_start', 'exam_opp3_end', 'recess_start', 'recess_end', 'orientation', 'registration', 'graduation', 'public_holiday', 'special_holiday', 'campus_event', 'other' )), semester INTEGER CHECK (semester IN (1, 2)), start_date DATE NOT NULL, end_date DATE, is_no_events_period INTEGER NOT NULL DEFAULT 0, source_url TEXT, source_type TEXT NOT NULL CHECK (source_type IN ('pdf_parsed', 'html_scraped', 'ical', 'manual', 'api')), last_verified_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), CHECK (end_date IS NULL OR end_date >= start_date) );
CREATE TABLE IF NOT EXISTS campus_events ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), university_id TEXT NOT NULL REFERENCES universities(id) ON DELETE CASCADE, campus_id TEXT REFERENCES university_campuses(id) ON DELETE SET NULL, title TEXT NOT NULL, description TEXT, event_date DATE NOT NULL, end_date DATE, start_time TIME, end_time TIME, location TEXT, category TEXT NOT NULL CHECK (category IN ( 'graduation', 'sports', 'registration', 'orientation', 'career', 'cultural', 'academic', 'admin', 'other' )), source_url TEXT, source_type TEXT NOT NULL CHECK (source_type IN ('pdf_parsed', 'html_scraped', 'ical', 'manual', 'api')), last_verified_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), CHECK (end_date IS NULL OR end_date >= event_date), CHECK ( start_time IS NULL OR end_time IS NULL OR end_time > start_time ) );
CREATE TABLE IF NOT EXISTS module_timetables ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), university_id TEXT NOT NULL REFERENCES universities(id) ON DELETE CASCADE, campus_id TEXT REFERENCES university_campuses(id) ON DELETE SET NULL, module_code TEXT NOT NULL, module_name TEXT, semester INTEGER NOT NULL CHECK (semester IN (1, 2)), year INTEGER NOT NULL, day_of_week TEXT NOT NULL CHECK (day_of_week IN ('Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday')), start_time TIME NOT NULL, end_time TIME NOT NULL, venue TEXT, group_code TEXT, lecturer TEXT, source_url TEXT, source_type TEXT NOT NULL CHECK (source_type IN ('pdf_parsed', 'html_scraped', 'ical', 'manual', 'api')), last_verified_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), CHECK (end_time > start_time) );
CREATE TABLE IF NOT EXISTS exam_timetables ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), university_id TEXT NOT NULL REFERENCES universities(id) ON DELETE CASCADE, campus_id TEXT REFERENCES university_campuses(id) ON DELETE SET NULL, module_code TEXT NOT NULL, module_name TEXT, opportunity INTEGER NOT NULL CHECK (opportunity IN (1, 2, 3)), year INTEGER NOT NULL, exam_date DATE NOT NULL, start_time TIME, end_time TIME, venue TEXT, paper_number INTEGER, source_url TEXT, source_type TEXT NOT NULL CHECK (source_type IN ('pdf_parsed', 'html_scraped', 'ical', 'manual', 'api')), last_verified_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), CHECK ( start_time IS NULL OR end_time IS NULL OR end_time > start_time ) );
CREATE TABLE IF NOT EXISTS enrolled_modules ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), student_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, university_id TEXT NOT NULL REFERENCES universities(id) ON DELETE CASCADE, campus_id TEXT REFERENCES university_campuses(id) ON DELETE SET NULL, module_code TEXT NOT NULL, module_name TEXT, year INTEGER NOT NULL, semester INTEGER CHECK (semester IN (1, 2)), credits INTEGER, is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE (student_id, module_code, year, semester) );
CREATE TABLE IF NOT EXISTS student_planner_events ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), student_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT, event_date DATE NOT NULL, end_date DATE, start_time TIME, end_time TIME, event_type TEXT NOT NULL CHECK (event_type IN ( 'semester_boundary', 'exam', 'class', 'assignment_due', 'campus_event', 'public_holiday', 'recess', 'personal' )), tier TEXT NOT NULL CHECK (tier IN ('tier1', 'tier2', 'tier3', 'manual')), source_ref_id TEXT, source_table TEXT, university_id TEXT REFERENCES universities(id) ON DELETE SET NULL, module_code TEXT, is_manual INTEGER NOT NULL DEFAULT 0, is_dismissed INTEGER NOT NULL DEFAULT 0, colour_tag TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), CHECK (end_date IS NULL OR end_date >= event_date), CHECK ( start_time IS NULL OR end_time IS NULL OR end_time > start_time ) );
CREATE TABLE IF NOT EXISTS student_university_profiles ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), student_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE UNIQUE, university_id TEXT NOT NULL REFERENCES universities(id) ON DELETE RESTRICT, campus_id TEXT REFERENCES university_campuses(id) ON DELETE SET NULL, faculty TEXT, year_of_study INTEGER CHECK (year_of_study BETWEEN 1 AND 8), qualification TEXT, student_number TEXT, onboarding_completed INTEGER NOT NULL DEFAULT 0, tier2_activated INTEGER NOT NULL DEFAULT 0, tier3_activated INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE TABLE IF NOT EXISTS calendar_sync_log ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), university_id TEXT REFERENCES universities(id) ON DELETE CASCADE, run_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), result TEXT NOT NULL CHECK (result IN ('success', 'partial', 'error')), rows_inserted INTEGER NOT NULL DEFAULT 0, errors TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE UNIQUE INDEX IF NOT EXISTS idx_academic_calendars_identity ON academic_calendars ( COALESCE(university_id, '00000000-0000-0000-0000-000000000000'), COALESCE(campus_id, '00000000-0000-0000-0000-000000000000'), year, event_type, start_date, COALESCE(end_date, start_date), label );
