CREATE UNIQUE INDEX IF NOT EXISTS idx_exam_timetables_identity ON exam_timetables ( university_id, COALESCE(campus_id, '00000000-0000-0000-0000-000000000000'), module_code, opportunity, year, exam_date, COALESCE(paper_number, 0) );
CREATE UNIQUE INDEX IF NOT EXISTS idx_student_planner_events_source ON student_planner_events ( student_id, source_table, source_ref_id, event_date, COALESCE(start_time, '00:00') ) WHERE source_ref_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_academic_calendars_university_year ON academic_calendars (university_id, year);
CREATE INDEX IF NOT EXISTS idx_exam_timetables_module_year ON exam_timetables (university_id, module_code, year, opportunity);
CREATE INDEX IF NOT EXISTS idx_module_timetables_module ON module_timetables (university_id, module_code, year, semester);
CREATE INDEX IF NOT EXISTS idx_enrolled_modules_student ON enrolled_modules (student_id, year);
CREATE INDEX IF NOT EXISTS idx_student_planner_events_student_date ON student_planner_events (student_id, event_date);
CREATE INDEX IF NOT EXISTS idx_student_planner_events_student_type ON student_planner_events (student_id, event_type);
CREATE INDEX IF NOT EXISTS idx_campus_events_university_date ON campus_events (university_id, event_date);
CREATE INDEX IF NOT EXISTS idx_student_university_profiles_university ON student_university_profiles (university_id, campus_id);
CREATE INDEX IF NOT EXISTS idx_calendar_sync_log_university_run ON calendar_sync_log (university_id, run_at DESC);
