CREATE TABLE IF NOT EXISTS bursaries ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), title text NOT NULL, provider text NOT NULL, provider_type text NOT NULL CHECK (provider_type IN ('nsfas','seta','corporate','ngo','government','other')), seta_name text, fields_of_study TEXT NOT NULL DEFAULT '{}', year_levels TEXT NOT NULL DEFAULT '{}', needs_based INTEGER NOT NULL DEFAULT 0, merit_based INTEGER NOT NULL DEFAULT 0, amount_min integer, amount_max integer, deadline date, description text, requirements TEXT NOT NULL DEFAULT '{}', link text NOT NULL, is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX IF NOT EXISTS idx_bursaries_active ON bursaries (is_active);
CREATE INDEX IF NOT EXISTS idx_bursaries_deadline ON bursaries (deadline) WHERE is_active = 1;
CREATE UNIQUE INDEX IF NOT EXISTS idx_bursaries_title_seed ON bursaries (title);
ALTER TABLE user_profiles ADD COLUMN field_of_study text;
ALTER TABLE user_profiles ADD COLUMN year_of_study text CHECK (year_of_study IN ('school','1','2','3','4','postgrad'));
ALTER TABLE user_profiles ADD COLUMN needs_financial_aid INTEGER NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS push_tokens ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token TEXT NOT NULL, platform TEXT NOT NULL CHECK (platform IN ('ios', 'android')), device_id TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE (user_id, device_id) );
CREATE INDEX IF NOT EXISTS idx_push_tokens_user_id ON push_tokens(user_id);
CREATE TABLE IF NOT EXISTS research_studies ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), code TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT, status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'recruiting', 'paused', 'closed')), ethics_ref TEXT, principal_investigator TEXT, current_consent_version TEXT NOT NULL DEFAULT 'v1', current_stimulus_version TEXT NOT NULL DEFAULT 'v1', min_age INTEGER NOT NULL DEFAULT 18, config TEXT NOT NULL DEFAULT '{}', opened_at TEXT, closed_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX IF NOT EXISTS idx_research_studies_status ON research_studies(status);
CREATE TABLE IF NOT EXISTS research_consents ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), study_id TEXT NOT NULL REFERENCES research_studies(id) ON DELETE CASCADE, user_id TEXT NULL REFERENCES users(id) ON DELETE SET NULL, participant_ref TEXT NOT NULL, consent_version TEXT NOT NULL, consent_scope TEXT NOT NULL DEFAULT '{}', is_minor INTEGER NOT NULL DEFAULT 0, guardian_consent_required INTEGER NOT NULL DEFAULT 0, guardian_consent_given_at TEXT, guardian_email TEXT, granted_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), withdrawn_at TEXT, withdrawal_reason TEXT, consent_ip_hash TEXT, user_agent_family TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE UNIQUE INDEX IF NOT EXISTS uq_research_consents_active ON research_consents(study_id, participant_ref) WHERE withdrawn_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_research_consents_study ON research_consents(study_id);
CREATE INDEX IF NOT EXISTS idx_research_consents_user ON research_consents(user_id);
CREATE TABLE IF NOT EXISTS research_sessions ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), study_id TEXT NOT NULL REFERENCES research_studies(id) ON DELETE CASCADE, consent_id TEXT NOT NULL REFERENCES research_consents(id) ON DELETE CASCADE, user_id TEXT NULL REFERENCES users(id) ON DELETE SET NULL, participant_ref TEXT NOT NULL, condition TEXT, stimulus_version TEXT NOT NULL, is_practice INTEGER NOT NULL DEFAULT 0, primary_task TEXT, reported_pass_count INTEGER, actual_pass_count INTEGER, pass_count_error INTEGER GENERATED ALWAYS AS ( CASE WHEN reported_pass_count IS NULL OR actual_pass_count IS NULL THEN NULL ELSE ABS(reported_pass_count - actual_pass_count) END ) STORED, device TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'in_progress' CHECK (status IN ('in_progress', 'completed', 'abandoned', 'withdrawn')), quality_flags TEXT NOT NULL DEFAULT '{}', started_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), completed_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX IF NOT EXISTS idx_research_sessions_study ON research_sessions(study_id);
CREATE INDEX IF NOT EXISTS idx_research_sessions_consent ON research_sessions(consent_id);
CREATE INDEX IF NOT EXISTS idx_research_sessions_status ON research_sessions(status);
CREATE INDEX IF NOT EXISTS idx_research_sessions_started ON research_sessions(started_at DESC);
CREATE TABLE IF NOT EXISTS research_trial_events ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), session_id TEXT NOT NULL REFERENCES research_sessions(id) ON DELETE CASCADE, study_id TEXT NOT NULL REFERENCES research_studies(id) ON DELETE CASCADE, seq INTEGER NOT NULL, event_type TEXT NOT NULL, event_time_ms BIGINT NOT NULL, client_ts TEXT, payload TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE UNIQUE INDEX IF NOT EXISTS uq_research_trial_events_seq ON research_trial_events(session_id, seq);
CREATE INDEX IF NOT EXISTS idx_research_trial_events_session ON research_trial_events(session_id, event_time_ms);
CREATE INDEX IF NOT EXISTS idx_research_trial_events_type ON research_trial_events(study_id, event_type);
CREATE TABLE IF NOT EXISTS research_noticing_outcomes ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), session_id TEXT NOT NULL REFERENCES research_sessions(id) ON DELETE CASCADE, study_id TEXT NOT NULL REFERENCES research_studies(id) ON DELETE CASCADE, critical_event_key TEXT NOT NULL, noticed INTEGER NOT NULL, notice_latency_ms INTEGER, confidence SMALLINT CHECK (confidence IS NULL OR (confidence BETWEEN 1 AND 5)), free_text TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE UNIQUE INDEX IF NOT EXISTS uq_research_noticing_outcome ON research_noticing_outcomes(session_id, critical_event_key);
CREATE INDEX IF NOT EXISTS idx_research_noticing_study ON research_noticing_outcomes(study_id, critical_event_key);
CREATE TABLE IF NOT EXISTS research_recall_responses ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), session_id TEXT NOT NULL REFERENCES research_sessions(id) ON DELETE CASCADE, study_id TEXT NOT NULL REFERENCES research_studies(id) ON DELETE CASCADE, prompt_key TEXT NOT NULL, response_value TEXT NOT NULL DEFAULT '{}', is_correct INTEGER, score NUMERIC, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE UNIQUE INDEX IF NOT EXISTS uq_research_recall_response ON research_recall_responses(session_id, prompt_key);
CREATE INDEX IF NOT EXISTS idx_research_recall_study ON research_recall_responses(study_id, prompt_key);
CREATE TABLE IF NOT EXISTS works ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), author_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK (kind IN ('paper', 'essay', 'literature', 'design', 'dataset_note', 'other')), layout TEXT NOT NULL DEFAULT 'written' CHECK (layout IN ('written', 'gallery')), title TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, abstract TEXT, body_md TEXT, discipline_tags TEXT NOT NULL DEFAULT '{}', license TEXT NOT NULL DEFAULT 'CC-BY-4.0' CHECK (license IN ('CC-BY-4.0', 'CC-BY-SA-4.0', 'CC-BY-NC-4.0', 'CC-BY-NC-SA-4.0', 'CC-BY-ND-4.0', 'CC0-1.0', 'all-rights-reserved')), status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'curated', 'withdrawn')), doi TEXT UNIQUE, cover_url TEXT, cover_storage_key TEXT, published_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX IF NOT EXISTS idx_works_author ON works(author_id, status);
CREATE INDEX IF NOT EXISTS idx_works_layout ON works(layout, status, published_at DESC);
CREATE INDEX IF NOT EXISTS idx_works_published ON works(status, published_at DESC);
CREATE TABLE IF NOT EXISTS work_versions ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), work_id TEXT NOT NULL REFERENCES works(id) ON DELETE CASCADE, version INTEGER NOT NULL, file_url TEXT, storage_key TEXT, image_urls TEXT NOT NULL DEFAULT '{}', changelog TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE (work_id, version) );
CREATE INDEX IF NOT EXISTS idx_work_versions_work ON work_versions(work_id, version DESC);
CREATE TABLE IF NOT EXISTS work_authors ( work_id TEXT NOT NULL REFERENCES works(id) ON DELETE CASCADE, user_id TEXT REFERENCES users(id) ON DELETE SET NULL, display_name TEXT NOT NULL, affiliation TEXT, ord INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (work_id, ord) );
CREATE INDEX IF NOT EXISTS idx_work_authors_user ON work_authors(user_id);
CREATE TABLE IF NOT EXISTS work_references ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), work_id TEXT NOT NULL REFERENCES works(id) ON DELETE CASCADE, raw TEXT NOT NULL, doi TEXT, ord INTEGER NOT NULL DEFAULT 0 );
CREATE INDEX IF NOT EXISTS idx_work_references_work ON work_references(work_id, ord);
