CREATE TABLE IF NOT EXISTS credit_wallets ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, venture TEXT NOT NULL, balance INTEGER NOT NULL DEFAULT 0, locked INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), CONSTRAINT uq_credit_wallets_user_venture UNIQUE (user_id, venture), CONSTRAINT ck_credit_wallets_venture CHECK (venture IN ( 'SCHOOL', 'AURA', 'SPHERE', 'NPC', 'ROCKIT', 'SCENE', 'LOGISTICS', 'V4NTAG3', 'DITSHGO_VENTURES' )), CONSTRAINT ck_credit_wallets_balance CHECK (balance >= 0), CONSTRAINT ck_credit_wallets_locked CHECK (locked >= 0) );
CREATE INDEX IF NOT EXISTS idx_credit_wallets_venture ON credit_wallets(venture);
CREATE TABLE IF NOT EXISTS credit_transactions ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, wallet_id TEXT REFERENCES credit_wallets(id) ON DELETE SET NULL, venture TEXT NOT NULL, type TEXT NOT NULL, source TEXT NOT NULL, amount INTEGER NOT NULL, balance_before INTEGER NOT NULL, balance_after INTEGER NOT NULL, description TEXT NOT NULL, metadata TEXT NOT NULL DEFAULT '{}', idempotency_key TEXT, reference_id TEXT, reference_type TEXT, processed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), CONSTRAINT ck_credit_transactions_venture CHECK (venture IN ( 'SCHOOL', 'AURA', 'SPHERE', 'NPC', 'ROCKIT', 'SCENE', 'LOGISTICS', 'V4NTAG3', 'DITSHGO_VENTURES' )), CONSTRAINT ck_credit_transactions_type CHECK (type IN ( 'EARN', 'SPEND', 'TRANSFER_IN', 'TRANSFER_OUT', 'BONUS', 'PENALTY', 'REFUND', 'ADJUSTMENT' )), CONSTRAINT ck_credit_transactions_amount CHECK (amount <> 0), CONSTRAINT ck_credit_transactions_balance CHECK (balance_after = balance_before + amount) );
CREATE UNIQUE INDEX IF NOT EXISTS uq_credit_transactions_idempotency ON credit_transactions(idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_credit_transactions_user ON credit_transactions(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_credit_transactions_venture ON credit_transactions(venture, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_credit_transactions_source ON credit_transactions(source, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_credit_transactions_ref ON credit_transactions(reference_id, reference_type);
CREATE TABLE IF NOT EXISTS credit_streaks ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, venture TEXT NOT NULL, streak_type TEXT NOT NULL DEFAULT 'daily', count INTEGER NOT NULL DEFAULT 0, start_date DATE NOT NULL DEFAULT CURRENT_DATE, end_date DATE, is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX IF NOT EXISTS idx_credit_streaks_user ON credit_streaks(user_id, venture);
CREATE INDEX IF NOT EXISTS idx_credit_streaks_active ON credit_streaks(is_active);
CREATE TABLE IF NOT EXISTS credit_venture_profiles ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, venture TEXT NOT NULL, external_id TEXT, metadata TEXT NOT NULL DEFAULT '{}', linked_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), last_synced_at TEXT, is_active INTEGER NOT NULL DEFAULT 1, CONSTRAINT uq_credit_venture_profiles_user_venture UNIQUE (user_id, venture) );
CREATE INDEX IF NOT EXISTS idx_credit_venture_profiles_venture ON credit_venture_profiles(venture);
CREATE INDEX IF NOT EXISTS idx_credit_venture_profiles_external ON credit_venture_profiles(external_id);
CREATE TABLE IF NOT EXISTS credit_redemptions ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, venture TEXT NOT NULL, source TEXT NOT NULL, amount INTEGER NOT NULL, item_id TEXT NOT NULL, item_type TEXT NOT NULL, item_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'PROCESSING', 'COMPLETED', 'FAILED', 'REFUNDED')), metadata TEXT NOT NULL DEFAULT '{}', processed_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), CONSTRAINT ck_credit_redemptions_amount CHECK (amount > 0) );
CREATE INDEX IF NOT EXISTS idx_credit_redemptions_user ON credit_redemptions(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_credit_redemptions_status ON credit_redemptions(status);
CREATE TABLE IF NOT EXISTS credit_rate_limits ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, venture TEXT NOT NULL, source TEXT NOT NULL, window_start TEXT NOT NULL, window_end TEXT NOT NULL, count INTEGER NOT NULL DEFAULT 0, max_count INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), CONSTRAINT uq_credit_rate_limits_window UNIQUE (user_id, venture, source, window_start), CONSTRAINT ck_credit_rate_limits_count CHECK (count >= 0 AND count <= max_count) );
CREATE INDEX IF NOT EXISTS idx_credit_rate_limits_user ON credit_rate_limits(user_id, venture);
CREATE TABLE IF NOT EXISTS credit_audit_log ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), user_id TEXT REFERENCES users(id) ON DELETE SET NULL, venture TEXT NOT NULL, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, old_value TEXT, new_value TEXT, performed_by TEXT, reason TEXT, ip_hash TEXT, user_agent_family TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX IF NOT EXISTS idx_credit_audit_log_user ON credit_audit_log(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_credit_audit_log_entity ON credit_audit_log(entity_type, entity_id);
CREATE TABLE IF NOT EXISTS store_vendors ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, tagline TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', accent TEXT NOT NULL DEFAULT '#C9A24B', badge TEXT NOT NULL DEFAULT '', icon_key TEXT NOT NULL DEFAULT 'store', config_json TEXT NOT NULL DEFAULT '{}', is_active INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX IF NOT EXISTS store_vendors_active_idx ON store_vendors(is_active, sort_order, name);
CREATE TABLE IF NOT EXISTS store_categories ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), store_id TEXT NOT NULL REFERENCES store_vendors(id) ON DELETE CASCADE, slug TEXT NOT NULL, name TEXT NOT NULL, parent_id TEXT REFERENCES store_categories(id) ON DELETE SET NULL, sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE (store_id, slug) );
