CREATE INDEX IF NOT EXISTS store_products_category_idx ON store_products(category_id);
CREATE TABLE IF NOT EXISTS store_orders ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'pending', subtotal_cents INTEGER NOT NULL DEFAULT 0, shipping_cents INTEGER NOT NULL DEFAULT 0, tax_cents INTEGER NOT NULL DEFAULT 0, total_cents INTEGER NOT NULL DEFAULT 0, currency TEXT NOT NULL DEFAULT 'ZAR', payment_provider TEXT, payment_intent_id TEXT, payment_status TEXT NOT NULL DEFAULT 'not_required', fulfillment_status TEXT NOT NULL DEFAULT 'pending', address_json TEXT NOT NULL DEFAULT '{}', notes_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX IF NOT EXISTS store_orders_user_idx ON store_orders(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS store_orders_status_idx ON store_orders(status, created_at DESC);
