CREATE INDEX IF NOT EXISTS store_order_items_order_idx ON store_order_items(order_id);
CREATE INDEX IF NOT EXISTS store_order_items_product_idx ON store_order_items(product_id);
CREATE INDEX IF NOT EXISTS store_order_items_store_idx ON store_order_items(store_id);
CREATE TABLE IF NOT EXISTS store_quote_requests ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), store_id TEXT NOT NULL REFERENCES store_vendors(id) ON DELETE CASCADE, user_id TEXT REFERENCES users(id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'pending', items_json TEXT NOT NULL DEFAULT '[]', customer_json TEXT NOT NULL DEFAULT '{}', notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX IF NOT EXISTS store_quote_requests_store_idx ON store_quote_requests(store_id, status, created_at DESC);
