ALTER TABLE users ADD COLUMN external_id TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS idx_users_institution_external_id ON users (institution_id, external_id) WHERE external_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS scim_events ( id TEXT DEFAULT (lower(hex(randomblob(16)))) PRIMARY KEY, institution_id TEXT NOT NULL REFERENCES institutions(id) ON DELETE CASCADE, operation text NOT NULL, resource_type text NOT NULL DEFAULT 'User', external_id text, user_id TEXT, payload TEXT, created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX IF NOT EXISTS scim_events_institution_idx ON scim_events (institution_id, created_at DESC);
CREATE TABLE IF NOT EXISTS scim_groups ( id TEXT DEFAULT (lower(hex(randomblob(16)))) PRIMARY KEY, institution_id TEXT NOT NULL REFERENCES institutions(id) ON DELETE CASCADE, external_id text NOT NULL, display_name text NOT NULL, created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE (institution_id, external_id) );
CREATE TABLE IF NOT EXISTS scim_group_members ( group_id TEXT NOT NULL REFERENCES scim_groups(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY (group_id, user_id) );
CREATE TABLE IF NOT EXISTS invoices ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), institution_id TEXT NOT NULL REFERENCES institutions(id) ON DELETE CASCADE, number TEXT NOT NULL UNIQUE, tier TEXT NOT NULL CHECK (tier IN ('E1','E2','E3','U1','U2','U3','G1')), billing_cycle TEXT NOT NULL DEFAULT 'annual' CHECK (billing_cycle IN ('monthly','semi_annual','annual','multi_year','custom')), license_seats INTEGER NOT NULL DEFAULT 0, currency TEXT NOT NULL DEFAULT 'ZAR', description TEXT NOT NULL DEFAULT '', net_amount_zar NUMERIC(14,2) NOT NULL, vat_zar NUMERIC(14,2) NOT NULL, gross_amount_zar NUMERIC(14,2) NOT NULL, amount_paid_zar NUMERIC(14,2) NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','issued','paid','partially_paid','overdue','cancelled')), payment_method TEXT NOT NULL DEFAULT 'eft' CHECK (payment_method IN ('eft','payfast','card','manual')), payment_provider_ref TEXT, issued_at TEXT, due_at TEXT, paid_at TEXT, cancelled_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX IF NOT EXISTS invoices_institution_idx ON invoices (institution_id, created_at DESC);
CREATE INDEX IF NOT EXISTS invoices_status_idx ON invoices (status);
CREATE INDEX IF NOT EXISTS invoices_number_idx ON invoices (number);
CREATE TABLE IF NOT EXISTS invoice_line_items ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), invoice_id TEXT NOT NULL REFERENCES invoices(id) ON DELETE CASCADE, description TEXT NOT NULL, quantity INTEGER NOT NULL DEFAULT 1, unit_price_zar NUMERIC(14,2) NOT NULL, net_zar NUMERIC(14,2) NOT NULL, vat_rate NUMERIC(5,4) NOT NULL DEFAULT 0.1500 );
CREATE INDEX IF NOT EXISTS invoice_line_items_invoice_idx ON invoice_line_items (invoice_id);
CREATE TABLE IF NOT EXISTS invoice_payments ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), invoice_id TEXT NOT NULL REFERENCES invoices(id) ON DELETE CASCADE, amount_zar NUMERIC(14,2) NOT NULL, method TEXT NOT NULL DEFAULT 'eft' CHECK (method IN ('eft','payfast','card','manual')), reference TEXT, provider_ref TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','cleared','failed','refunded')), received_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX IF NOT EXISTS invoice_payments_invoice_idx ON invoice_payments (invoice_id);
CREATE TABLE IF NOT EXISTS lti_registrations ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), institution_id TEXT NOT NULL REFERENCES institutions(id) ON DELETE CASCADE, issuer TEXT NOT NULL, client_id TEXT NOT NULL, platform_name TEXT NOT NULL DEFAULT 'LMS', auth_login_url TEXT NOT NULL, auth_token_url TEXT NOT NULL, jwks_url TEXT NOT NULL, deployment_id TEXT, tool_context TEXT NOT NULL DEFAULT 'lesson', claim_nonce_ttl_sec INTEGER NOT NULL DEFAULT 600, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE (institution_id, issuer, client_id) );
CREATE INDEX IF NOT EXISTS lti_registrations_institution_idx ON lti_registrations (institution_id);
CREATE TABLE IF NOT EXISTS lti_launch_states ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), nonce TEXT NOT NULL UNIQUE, state TEXT NOT NULL, used INTEGER NOT NULL DEFAULT 0, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX IF NOT EXISTS lti_launch_states_nonce_idx ON lti_launch_states (nonce);
CREATE TABLE IF NOT EXISTS lti_launch_events ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), institution_id TEXT NOT NULL REFERENCES institutions(id) ON DELETE CASCADE, registration_id TEXT REFERENCES lti_registrations(id) ON DELETE SET NULL, user_id TEXT REFERENCES users(id) ON DELETE SET NULL, issuer TEXT, client_id TEXT, deployment_id TEXT, resource_link_id TEXT, context_title TEXT, roles_lis TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX IF NOT EXISTS lti_launch_events_institution_idx ON lti_launch_events (institution_id, created_at DESC);
CREATE TABLE IF NOT EXISTS institution_usage_daily ( institution_id TEXT NOT NULL REFERENCES institutions(id) ON DELETE CASCADE, day DATE NOT NULL, active_users INTEGER NOT NULL DEFAULT 0, logins INTEGER NOT NULL DEFAULT 0, sessions INTEGER NOT NULL DEFAULT 0, lesson_engagements INTEGER NOT NULL DEFAULT 0, ai_requests INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY (institution_id, day) );
CREATE INDEX IF NOT EXISTS usage_daily_inst_day_idx ON institution_usage_daily (institution_id, day DESC);
CREATE TABLE IF NOT EXISTS institution_ai_usage ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), institution_id TEXT NOT NULL REFERENCES institutions(id) ON DELETE CASCADE, user_id TEXT REFERENCES users(id) ON DELETE SET NULL, provider TEXT NOT NULL DEFAULT 'openai', model TEXT NOT NULL DEFAULT 'gpt-4o-mini', purpose TEXT NOT NULL DEFAULT 'tutor', prompt_tokens INTEGER NOT NULL DEFAULT 0, completion_tokens INTEGER NOT NULL DEFAULT 0, total_tokens INTEGER NOT NULL DEFAULT 0, cost_zar NUMERIC(12,6) NOT NULL DEFAULT 0, performed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX IF NOT EXISTS ai_usage_inst_time_idx ON institution_ai_usage (institution_id, performed_at DESC);
CREATE INDEX IF NOT EXISTS ai_usage_inst_day_idx ON institution_ai_usage (institution_id, performed_at);
ALTER TABLE institution_settings ADD COLUMN onboarded_user_count INTEGER NOT NULL DEFAULT 0;
ALTER TABLE institution_settings ADD COLUMN ai_config TEXT NOT NULL DEFAULT '{}';
CREATE TABLE IF NOT EXISTS subject_access_requests ( id TEXT PRIMARY KEY, requestor_user_id TEXT NOT NULL, institution_id TEXT, request_type TEXT NOT NULL CHECK (request_type IN ('access', 'erasure')), status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','in_progress','fulfilled','rejected','erased')), details TEXT, channel TEXT DEFAULT 'self-service', sla_due_at TEXT NOT NULL, snapshot_path TEXT, fulfilled_at TEXT, fulfilled_by TEXT, fulfilled_notes TEXT, erased_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX IF NOT EXISTS idx_dsar_status_sla ON subject_access_requests(status, sla_due_at);
CREATE INDEX IF NOT EXISTS idx_dsar_requestor ON subject_access_requests(requestor_user_id);
CREATE INDEX IF NOT EXISTS idx_dsar_institution ON subject_access_requests(institution_id);
CREATE TABLE IF NOT EXISTS retention_policies ( policy_key TEXT PRIMARY KEY, display_name TEXT NOT NULL, policy_value_years TEXT, effective_from TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_by TEXT, updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
